<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ApiKeyClient\Application\Usecase\Create;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Access\ApiKeyClient\Application\Service\Visibility\ApiKeyClientVisibilityService;
use Civi\Lughauth\Features\Access\ApiKeyClient\Domain\ApiKeyClient;
use Civi\Lughauth\Features\Access\ApiKeyClient\Domain\Gateway\ApiKeyClientCommandRepositoryGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ApiKeyClientCreateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ApiKeyClientVisibilityService $visibility,
        private readonly ApiKeyClientCommandRepositoryGateway $writer,
    ) {
    }

    public function allowCreate(): Allow
    {
        $this->logDebug("Check allow of create usecase for Api key client");
        $span = $this->startSpan("Check allow of create usecase for Api key client");
        try {
            $result = $this->dispatcher->dispatch(new ApiKeyClientCreateAllowDecision(Allow::allowed('create', 'Allowed to create by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function create(ApiKeyClientCreateParams $params): ApiKeyClientCreateResult
    {
        $this->logDebug("Run create usecase for Api key client");
        $span = $this->startSpan("Run create usecase for Api key client");
        try {
            $allow = $this->allowCreate();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to create Api key client');
            }
            $this->dispatcher->dispatch(new ApiKeyClientCreateCheck($params));
            $attributes = $this->visibility->copyWithFixed($params->toAttributes());
            $enriched = $this->dispatcher->dispatch(new ApiKeyClientCreateEnrich($params, $attributes));
            $input = $enriched->getEnrichedAttributes();
            $entity = ApiKeyClient::create($input);
            $result = $this->writer->create(
                $entity,
                fn (ApiKeyClient $created) =>
                            $this->visibility->checkVisibility($created)
            );
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new ApiKeyClientCreateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
